// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/album", wrapper.GetAlbums)
	m.HandleFunc("GET "+options.BaseURL+"/album/{albumID}", wrapper.GetAlbumID)
	m.HandleFunc("DELETE "+options.BaseURL+"/favor", wrapper.DeleteFavor)
	m.HandleFunc("GET "+options.BaseURL+"/favor", wrapper.GetFavor)
	m.HandleFunc("POST "+options.BaseURL+"/favor", wrapper.AddFavor)
	m.HandleFunc("GET "+options.BaseURL+"/likes", wrapper.GetLikes)
	m.HandleFunc("DELETE "+options.BaseURL+"/listening-history", wrapper.DeleteListeningFromLH)
	m.HandleFunc("GET "+options.BaseURL+"/listening-history", wrapper.GetLH)
	m.HandleFunc("POST "+options.BaseURL+"/listening-history", wrapper.AddListeningToLH)
	m.HandleFunc("GET "+options.BaseURL+"/music", wrapper.GetAllMusic)
	m.HandleFunc("DELETE "+options.BaseURL+"/music/like", wrapper.DeleteMusicLike)
	m.HandleFunc("POST "+options.BaseURL+"/music/like", wrapper.PostMusicLike)
	m.HandleFunc("POST "+options.BaseURL+"/music/play", wrapper.PostMusicPlay)
	m.HandleFunc("GET "+options.BaseURL+"/music/{musicID}", wrapper.GetMusic)
	m.HandleFunc("GET "+options.BaseURL+"/ping", wrapper.GetPing)
	m.HandleFunc("GET "+options.BaseURL+"/playlist/my", wrapper.GetMyPlaylists)
	m.HandleFunc("GET "+options.BaseURL+"/playlist/public", wrapper.GetPublicPlaylists)
	m.HandleFunc("DELETE "+options.BaseURL+"/playlist/{playlistID}", wrapper.DeletePlaylist)
	m.HandleFunc("GET "+options.BaseURL+"/playlist/{playlistID}", wrapper.GetPlaylistTracks)
	m.HandleFunc("PATCH "+options.BaseURL+"/playlist/{playlistID}", wrapper.UpdatePlaylist)
	m.HandleFunc("POST "+options.BaseURL+"/playlist/{playlistID}/add", wrapper.AddMusicToPlaylist)
	m.HandleFunc("GET "+options.BaseURL+"/profile", wrapper.GetProfile)
	m.HandleFunc("POST "+options.BaseURL+"/register", wrapper.Register)
	m.HandleFunc("GET "+options.BaseURL+"/users", wrapper.GetUsers)
	m.HandleFunc("GET "+options.BaseURL+"/users/{userID}", wrapper.GetUserProfile)
	m.HandleFunc("GET "+options.BaseURL+"/users/{userID}/albums", wrapper.GetUserAlbums)
	m.HandleFunc("GET "+options.BaseURL+"/users/{userID}/playlists", wrapper.GetUserPlaylists)

	return m
}

